{
  "report": "Síntese (até 03/02/2025): RECV3 mostra uma tendência de baixa bem estabelecida desde o período mostrado. O preço está abaixo das médias de curto e médio prazo e as médias (MM20 e MM50) permanecem abaixo da MM200, todas com inclinação descendente — sinal clássico de tendência baixista. O momentum é fraco: o MACD encontra‑se próximo de zero e voltou a ficar levemente negativo (histograma pequeno em vermelho) e o RSI está em torno de 45, indicando ausência de sobrecompra ou sobrevenda. As Bandas de Bollinger estão relativamente apertadas nas últimas sessões (baixa volatilidade), com o preço rondando a banda média/inferior, o que traduz consolidação e risco de continuidade da queda se houver rompimento para baixo. O volume não tem mostrado confirmação consistente dos rallies: houve picos isolados em novembro e dezembro que geraram repiques, mas sem sustentação por volume nos aumentos de preço subsequentes.",
  "signal": "Baixa",
  "support_levels": [
    15.20,
    15.60
  ],
  "resistance_levels": [
    16.80,
    17.20,
    18.80
  ],
  "indicator_readings": [
    {
      "indicator": "Preço (fechamento)",
      "reading": "≈ R$16,00 (fechamento em 2025-02-03)",
      "interpretation": "Abaixo das médias de curto e médio prazo; preço próximo à banda média/inferior das Bollinger — viés de baixa no curto-médio prazo."
    },
    {
      "indicator": "MM20",
      "reading": "≈ R$16,10",
      "interpretation": "Inclinação descendente; MM20 abaixo da MM50 e da MM200, confirma tendência de baixa de curto/médio prazo."
    },
    {
      "indicator": "MM50",
      "reading": "≈ R$16,70",
      "interpretation": "MM50 também descendente e atuando como resistência dinâmica próxima (R$16,8)."
    },
    {
      "indicator": "MM200",
      "reading": "≈ R$18,80",
      "interpretation": "MM200 em nível bem acima do preço atual — tendência de longo prazo ainda baixista; nível importante de resistência."
    },
    {
      "indicator": "EMA9",
      "reading": "≈ R$15,95",
      "interpretation": "EMA9 próximo ao preço e ligeiramente abaixo da EMA21 — curto prazo com momentum fraco/negativo."
    },
    {
      "indicator": "EMA21",
      "reading": "≈ R$16,05",
      "interpretation": "EMA21 acompanha MM20/EMA9 confirmando falta de força de alta."
    },
    {
      "indicator": "MACD",
      "reading": "Linha MACD ≈ ligeiramente negativa; histograma pequeno em vermelho",
      "interpretation": "Momentum enfraquecido; recente cruzamento para baixo indica risco de continuação da baixa enquanto não vier cruzamento e histograma positivo sustentado."
    },
    {
      "indicator": "Bandas de Bollinger (20,2σ)",
      "reading": "Bandas relativamente estreitas; preço na banda média/inferior",
      "interpretation": "Baixa volatilidade recente (compressão). Compressão precede movimentos direcionais — atenção a rompimentos com volume."
    },
    {
      "indicator": "RSI (14)",
      "reading": "≈ 45",
      "interpretation": "Neutro/levemente fraco — sem condição de sobrevenda; não indica reversão clara no momento."
    },
    {
      "indicator": "Volume",
      "reading": "Picos isolados (nov/dez); média sem tendência clara",
      "interpretation": "Rallies não foram consistentemente confirmados por aumento de volume, reduzindo a convicção de recuperações."
    }
  ]
}
